<script setup>
import Checkbox from '@scaffold/components/Checkbox.vue';
import PasskeyVerify from '@scaffold/components/PasskeyVerify.vue';
import InputError from '@scaffold/components/InputError.vue';
import PrimaryButton from '@scaffold/components/PrimaryButton.vue';
import TextInput from '@scaffold/components/TextInput.vue';
import { Head as InertiaHead, Link, useForm } from '@inertiajs/vue3';
import { request as requestPasswordReset } from '@app/routes/password';

defineProps({
    canUsePasskeys: Boolean,
    canResetPassword: {
        type: Boolean,
    },
    status: {
        type: String,
    },
});

const form = useForm({
    email: '',
    password: '',
    remember: false,
});

const forgotPasswordUrl = requestPasswordReset.url();

const submit = () => {
    form.post('/login', {
        onFinish: () => form.reset('password'),
    });
};
</script>

<template>
    <div>
        <InertiaHead title="Pieteikties" />

        <div v-if="status" class="mb-3 text-center text-success" role="status">
            {{ status }}
        </div>
        <div class="row justify-content-center">
            <div class="lg:col-4 md:col-6 sm:col-8 ms-auto me-auto">
                <div class="card login-card">
                    <div class="card-header card-header-primary text-center">
                        <h4 class="card-title">Pieteikties</h4>
                    </div>
                    <form @submit.prevent="submit">
                        <div class="card-body">
                            <span class="bmd-form-group">
                                <div class="input-group">
                                    <div class="input-group-prepend">
                                        <span class="input-group-text">
                                            <i class="material-icons">mail</i>
                                        </span>
                                    </div>
                                    <TextInput
                                        id="email"
                                        type="text"
                                        class="form-control"
                                        v-model="form.email"
                                        required
                                        autofocus
                                        autocomplete="email"
                                    />
                                </div>
                                <input-error :message="form.errors.email" />
                            </span>
                            <span class="bmd-form-group">
                                <div class="input-group">
                                    <div class="input-group-prepend">
                                        <span class="input-group-text">
                                            <i class="material-icons"
                                                >lock_outline</i
                                            >
                                        </span>
                                    </div>
                                    <TextInput
                                        id="password"
                                        type="password"
                                        class="form-control"
                                        v-model="form.password"
                                        required
                                        autocomplete="current-password"
                                    />
                                </div>
                                <input-error :message="form.errors.password" />
                            </span>
                            <div class="form-group row">
                                <div class="col-md-6 offset-md-4 ps-6">
                                    <Checkbox
                                        id="remember"
                                        name="remember"
                                        v-model:checked="form.remember"
                                    >
                                        Atcerēties mani
                                    </Checkbox>
                                </div>
                            </div>
                        </div>
                        <div class="card-footer justify-content-center">
                            <PrimaryButton
                                class="btn btn-primary"
                                :class="{ 'opacity-25': form.processing }"
                                :disabled="form.processing"
                            >
                                Ienākt
                            </PrimaryButton>
                        </div>
                    </form>
                    <PasskeyVerify
                        v-if="canUsePasskeys"
                        :disabled="form.processing"
                    />
                    <p v-if="canResetPassword" class="text-center mb-3">
                        <Link :href="forgotPasswordUrl">Aizmirsāt paroli?</Link>
                    </p>
                </div>
            </div>
        </div>
    </div>
</template>

<script>
export default {
    mounted() {
        document.body.classList.add('login-page', 'sidebar-collapse');
    },
    beforeUnmount() {
        document.body.classList.remove('login-page', 'sidebar-collapse');
    },
};
</script>

<style scoped>
.login-card .form-control:focus {
    outline: 2px solid transparent;
}

@media (max-width: 991.98px) {
    .login-card .form-control {
        font-size: 1rem;
    }
}
</style>
